// Generates web/static/tokens.css (Material 3 color roles) from one seed color.
// Run via scripts/vendor/build.sh; the output is committed, nothing runs at deploy time.
import { argbFromHex, hexFromArgb, Hct, SchemeTonalSpot, MaterialDynamicColors as M, customColor } from "@material/material-color-utilities";

const SEED = "#00677a"; // azul-petróleo
const CUSTOM = [
  { name: "success", value: argbFromHex("#2e8b57"), blend: true },
  { name: "warning", value: argbFromHex("#d99a00"), blend: true },
];
const ROLES = [
  "primary", "onPrimary", "primaryContainer", "onPrimaryContainer",
  "secondary", "onSecondary", "secondaryContainer", "onSecondaryContainer",
  "tertiary", "onTertiary", "tertiaryContainer", "onTertiaryContainer",
  "error", "onError", "errorContainer", "onErrorContainer",
  "background", "onBackground", "surface", "onSurface", "surfaceVariant", "onSurfaceVariant",
  "outline", "outlineVariant", "shadow", "scrim", "inverseSurface", "inverseOnSurface", "inversePrimary",
  "surfaceDim", "surfaceBright", "surfaceContainerLowest", "surfaceContainerLow", "surfaceContainer",
  "surfaceContainerHigh", "surfaceContainerHighest", "surfaceTint",
];
const kebab = (s) => s.replace(/[A-Z]/g, (m) => "-" + m.toLowerCase());
const source = argbFromHex(SEED);
const custom = CUSTOM.map((c) => customColor(source, c));

const block = (dark) => {
  const scheme = new SchemeTonalSpot(Hct.fromInt(source), dark, 0);
  const out = ROLES.map((r) => `  --md-sys-color-${kebab(r)}: ${hexFromArgb(M[r].getArgb(scheme))};`);
  for (const c of custom) {
    const t = dark ? c.dark : c.light;
    const n = c.color.name;
    out.push(`  --brp-${n}: ${hexFromArgb(t.color)};`, `  --brp-on-${n}: ${hexFromArgb(t.onColor)};`,
      `  --brp-${n}-container: ${hexFromArgb(t.colorContainer)};`, `  --brp-on-${n}-container: ${hexFromArgb(t.onColorContainer)};`);
  }
  return out.join("\n");
};
const light = block(false);
const dark = block(true);
const indent = (s, n) => s.replace(/^/gm, " ".repeat(n));
console.log(`/* Generated by scripts/vendor/theme.mjs from seed ${SEED}. Do not edit by hand. */
:root, :root[data-theme="light"] {
  color-scheme: light;
${light}
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
${indent(dark, 2)}
  }
}
:root[data-theme="dark"] {
  color-scheme: dark;
${dark}
}`);
